function archiveService(f,{loseBegin=false,loseStart=false,corruptRead=false,canonicalRead=false,stopAfterVideo=false}={}){const calls=[],archives=[],chunks=new Map();let draft,returned=false;const call=async b=>{calls.push(b);if(b.action==='local_review_draft_read'){if(!draft)throw Object.assign(Error('not found'),{status:404});return{draft:{...draft,status:returned?'returned':'staging'},archives:canonicalRead?JSON.parse(JSON.stringify(archives,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x)):structuredClone(archives)};}if(b.action==='local_review_draft_begin'){assert.equal(b.voice.kind,'ordinary-review');assert.equal(b.voice.owner_clone_used,false);assert.equal(b.voice.script_text_sha256,sha('SYNTHETIC unchanged script'));assert.equal(b.project.kind,'local-editor-project');assert.equal(b.cost,0);assert.equal(b.publication_authorized,false);draft={local_draft_id:'lrd_'+'1'.repeat(64),binding:f.binding,scope_id:f.binding.scope_id,scope_hash:b.scope_hash,request:{video:b.video,project:b.project,qa:b.qa,request_id:b.request_id,delivery_mode:b.delivery_mode,...(b.project_archive?{project_archive:b.project_archive}:{})}};if(loseBegin){loseBegin=false;throw Error('unknown begin response');}return{draft};}if(b.action==='site_archive_start'){if(stopAfterVideo&&b.file.role==='project_archive'){stopAfterVideo=false;throw Error('SYNTHETIC stop after confirmed video journal');}const a={site_archive_id:'sitefile_'+String(archives.length+1).repeat(64),file:b.file,status:'uploading',part_count:Math.ceil(b.file.size_bytes/PART),part_size:PART};archives.push(a);chunks.set(a.site_archive_id,[]);if(loseStart){loseStart=false;throw Error('unknown start response');}return{archive:structuredClone(a)};}const a=archives.find(a=>a.site_archive_id===b.site_archive_id);if(b.action==='site_archive_part'){const bytes=Buffer.from(b.chunk_base64,'base64');assert.equal(sha(bytes),b.chunk_sha256);chunks.get(a.site_archive_id)[b.part]=bytes;return{part:b.part};}if(b.action==='site_archive_finalize'){const bytes=Buffer.concat(chunks.get(a.site_archive_id));assert.equal(bytes.length,a.file.size_bytes);assert.equal(sha(bytes),a.file.sha256);a.status='sealed';return{archive:structuredClone(a)};}if(b.action==='site_archive_read_part'){let bytes=chunks.get(a.site_archive_id)[b.part];if(corruptRead)bytes=Buffer.concat([bytes,Buffer.from('corrupt')]);return{site_archive_id:a.site_archive_id,part:b.part,chunk_base64:bytes.toString('base64'),chunk_sha256:sha(bytes),size_bytes:bytes.length,part_count:a.part_count,part_size:PART};}if(b.action==='site_archive_confirm'){assert.equal(b.materialized_sha256,a.file.sha256);assert.equal(b.size_bytes,a.file.size_bytes);a.status='confirmed';return{archive:structuredClone(a)};}if(b.action==='local_review_draft_return'){if(stopAfterVideo){stopAfterVideo=false;throw Error('SYNTHETIC return response lost before submit');}assert.equal(archives.length,1);assert.ok(archives.every(a=>a.status==='confirmed'));returned=true;return{draft:{...draft,status:'returned'}};}throw Error('Unexpected external action '+b.action);};return{call,calls,archives};}

