 const resumed=await uploadLocalReviewFiles(f.job,f.result,{root:f.root,call:s.call}),id=s.archives[0].site_archive_id;assert.equal(resumed.status,'local-review-returned');assert.equal(s.calls.filter(c=>c.action==='local_review_draft_begin').length,1);assert.equal(s.calls.filter(c=>c.action==='site_archive_start').length,1);for(const part of Array.from({length:SITE_ARCHIVE_PART_CONCURRENCY},(_,i)=>i+1))assert.equal(s.calls.filter(c=>c.action==='site_archive_part'&&c.site_archive_id===id&&c.part===part).length,1);assert.equal(s.calls.filter(c=>c.action==='site_archive_part'&&c.site_archive_id===id&&c.part===0).length,2);
