test('owner approved preview restoration reuses exact original receipt and performs no generation',async t=>{const f=fixture(t),{restoreOwnerApprovedPreview}=await import('../scripts/private-review-continuation.mjs'),voice=f.result.files.find(x=>x.role==='voice'),video=f.result.files.find(x=>x.role==='video'),project=f.result.files.find(x=>x.role==='project'),rid='lrd_'+'e'.repeat(64),sid='sitefile_'+'f'.repeat(64),zipid='sitefile_'+'9'.repeat(64),prior={sha256:'1'.repeat(64),provider_job_id:rid,storage:'site-private-r2',site_archive_id:sid,qa:{local_review_draft_id:rid,project_archive_id:zipid,project_sha256:'2'.repeat(64),voice_kind:'ordinary-review',owner_voice_used:false,audio_sha256:voice.sha256,voice_script_text_sha256:sha('SYNTHETIC unchanged script'),quality_approved:false,publication_authorized:false}},artifact=JSON.stringify(prior),m={id:'local_review_video_'+'3'.repeat(64),node:'video',revision:1,artifact_version:4,mode_epoch:1,status:'awaiting_human',report:null,artifact,artifact_hash:sha(artifact)},pid='wipv_'+'c'.repeat(64),note=JSON.stringify({schema:'human-preview-feedback-v1',preview_id:pid,video_sha256:video.sha256,decision:'approve',feedback:''});f.job.review_mode='node';f.job.milestones.push(m);f.job.reviews=[{revision:1,content_hash:prior.sha256,decision:'local_review_draft_return_v1',note:JSON.stringify({schema:'local-review-draft-return-v1',local_draft_id:rid,milestone_id:m.id,binding:{...f.binding,candidate_id:rid,candidate_sha256:prior.sha256},archives:{video:sid,project_archive:zipid},quality_approved:false,publication_authorized:false,new_paid_calls:0})},{id:'owner-review',revision:1,reviewer:f.job.owner_id,content_hash:video.sha256,decision:'human_preview_feedback',created_at:'2026-01-01',note}];Object.assign(f.result,{schema:'private-review-producer-receipt-v1',status:'files-ready'});const file=path.join(f.out,'producer-receipt.json'),bytes=Buffer.from(JSON.stringify(f.result));fs.writeFileSync(file,bytes);const pending=nativePreparationPendingVideo(f.job);assert.ok(pending);const h={status:'completed',lease_until:null,binding:f.binding,base_pending_video:pending,checkpoint:{artifacts:[{kind:'local-file',purpose:'render-receipt',file:path.relative(f.root,file).split(path.sep).join('/'),sha256:sha(bytes),size_bytes:bytes.length}]}},preview={id:pid,revision:1,job_revision:1,sha256:video.sha256,size:video.size_bytes,review:{...JSON.parse(note),created_at:'2026-01-01'}},calls=[];const call=async b=>{calls.push(b.action);return b.action==='read'?{job:f.job}:b.action==='native_preparation_read'?{handoff:h}:{preview}};let observed;const r=await restoreOwnerApprovedPreview(ID,{call,root:f.root,upload:async(j,result,opts)=>{observed=opts.approvedPreviewRestore;assert.equal(result.files.find(x=>x.role==='video').sha256,preview.sha256);return{status:'local-review-returned'}}});assert.equal(r.status,'local-review-returned');assert.equal(observed.feedback_id,'owner-review');assert.equal(observed.base_hash,m.artifact_hash);assert.deepEqual(calls,['read','native_preparation_read','wip_video_read']);preview.review.decision='revise';await assert.rejects(()=>restoreOwnerApprovedPreview(ID,{call,root:f.root,upload:()=>{throw Error('must not upload')}}));});

